package org.example.backend.service;
import org.example.backend.entity.AiConversationEntity;
import org.example.backend.mapper.AiConversationMapper;
import org.example.backend.mapper.ModuleRecordMapper;
import org.example.backend.service.impl.AiConversationServiceImpl;
import org.example.backend.service.impl.ModuleRecordServiceImpl;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class JsonPersistenceBehaviorTest {
    @Test void conversationSaveLimitsHistoryAndPayloadSizesWithoutLosingUserScope(){AiConversationMapper mapper=mock(AiConversationMapper.class);AiConversationService service=new AiConversationServiceImpl(mapper);List<Map<String,Object>> input=new ArrayList<>();for(int index=0;index<35;index++)input.add(Map.of("id","x".repeat(130)+index,"title","t".repeat(130),"preview","p".repeat(310),"updatedAt","12345","messages",List.of(Map.of("role","user","content","内容"))));service.saveConversations(7,input);var entities=ArgumentCaptor.forClass(AiConversationEntity.class);verify(mapper,times(30)).upsertConversation(entities.capture());AiConversationEntity first=entities.getValue();assertEquals(7,first.getUserId());assertEquals(120,first.getConversationId().length());assertEquals(120,first.getTitle().length());assertEquals(300,first.getPreview().length());assertEquals(12345L,first.getUpdatedAtMillis());assertTrue(first.getMessagesJson().contains("内容"));verify(mapper).trimUserConversations(7,30);verify(mapper).listByUser(7);}
    @Test void nullConversationDefaultsAndCorruptHistoryRemainUsable(){AiConversationMapper mapper=mock(AiConversationMapper.class);AiConversationService service=new AiConversationServiceImpl(mapper);List<AiConversationEntity> saved=new ArrayList<>();when(mapper.upsertConversation(any())).thenAnswer(call->{saved.add(call.getArgument(0));return 1;});when(mapper.listByUser(7)).thenAnswer(call->saved);List<Map<String,Object>> result=service.saveConversations(7,Arrays.asList(null,Map.of("id"," second ","messages","invalid","updatedAt",10)));assertEquals("新的咨询",result.get(0).get("title"));assertEquals("暂无对话内容",result.get(0).get("preview"));assertTrue(result.get(0).get("id").toString().startsWith("conversation-"));assertEquals("second",result.get(1).get("id"));assertEquals(10L,result.get(1).get("updatedAt"));assertEquals(List.of(),result.get(1).get("messages"));for(String json:Arrays.asList(null,"","malformed","null")){saved.get(0).setMessagesJson(json);assertEquals(List.of(),service.listConversations(7).get(0).get("messages"));}}
    @Test void emptySyncDoesNotDeleteHistoryAndExplicitDeletionRequiresUserAndId(){AiConversationMapper mapper=mock(AiConversationMapper.class);AiConversationService service=new AiConversationServiceImpl(mapper);service.saveConversations(7,null);service.saveConversations(7,List.of());verify(mapper,never()).upsertConversation(any());verify(mapper,never()).trimUserConversations(anyInt(),anyInt());service.deleteConversation(7,"conversation-1");verify(mapper).deleteByUserAndConversationId(7,"conversation-1");assertThrows(IllegalArgumentException.class,()->service.deleteConversation(7,""));assertThrows(IllegalArgumentException.class,()->service.listConversations(0));assertThrows(IllegalArgumentException.class,()->service.saveConversations(null,List.of()));}
    @Test void moduleReplacementUsesStableKeyFallbacksAndParsesSavedJson(){ModuleRecordMapper mapper=mock(ModuleRecordMapper.class);BusinessLoopService loop=mock(BusinessLoopService.class);ModuleRecordService service=new ModuleRecordServiceImpl(mapper,new ObjectMapper(),loop);List<Map<String,Object>> records=List.of(Map.of("id",1,"name","名称"),Map.of("code","C1"),Map.of("name","名称"),Map.of("course","课程"),Map.of("other",true));assertEquals(records,service.replaceModuleRecords("templates",records));verify(mapper).insertRecord(eq("templates"),eq("1"),contains("名称"));verify(mapper).insertRecord(eq("templates"),eq("C1"),anyString());verify(mapper).insertRecord(eq("templates"),eq("名称"),anyString());verify(mapper).insertRecord(eq("templates"),eq("课程"),anyString());verify(mapper).insertRecord(eq("templates"),isNull(),anyString());when(mapper.listRecordJson("templates")).thenReturn(List.of("{\"id\":1,\"name\":\"名称\"}"));assertEquals("名称",service.listModuleRecords("templates").get(0).get("name"));verify(loop).recordEvent("module-record","batch-save","templates","已保存",Map.of("count",5));}
    @Test void operationEventPersistenceAvoidsRecursiveAuditAndResetClearsRecords(){ModuleRecordMapper mapper=mock(ModuleRecordMapper.class);BusinessLoopService loop=mock(BusinessLoopService.class);ModuleRecordService service=new ModuleRecordServiceImpl(mapper,new ObjectMapper(),loop);service.replaceModuleRecords("operation-events",List.of(Map.of("id",1)));service.resetModuleRecords("operation-events");verifyNoInteractions(loop);assertEquals(List.of(),service.replaceModuleRecords("templates",null));assertEquals(List.of(),service.resetModuleRecords("templates"));verify(loop).recordEvent("module-record","reset","templates","已清空",Map.of("moduleName","templates"));}
    @Test void malformedModuleJsonFailsExplicitlyInsteadOfSilentlyDroppingData(){ModuleRecordMapper mapper=mock(ModuleRecordMapper.class);ModuleRecordService service=new ModuleRecordServiceImpl(mapper,new ObjectMapper(),mock(BusinessLoopService.class));when(mapper.listRecordJson("module")).thenReturn(List.of("bad json"));assertThrows(IllegalStateException.class,()->service.listModuleRecords("module"));Map<String,Object> cyclic=new HashMap<>();cyclic.put("self",cyclic);assertThrows(IllegalStateException.class,()->service.replaceModuleRecords("module",List.of(cyclic)));}
}
